43	export function isIntervalOrLogScale(scale: Scale): scale is LogScale | IntervalScale {
44	    return scale.type === 'interval' || scale.type === 'log';
45	}
46	/**
47	 * @param extent Both extent[0] and extent[1] should be valid number.
48	 *               Should be extent[0] < extent[1].
49	 * @param splitNumber splitNumber should be >= 1.
50	 */
51	export function intervalScaleNiceTicks(
52	    extent: [number, number],
53	    spanWithBreaks: number,
54	    splitNumber: number,
55	    minInterval?: number,
56	    maxInterval?: number
57	): intervalScaleNiceTicksResult {
58	
59	    const result = {} as intervalScaleNiceTicksResult;
60	
61	    let interval = result.interval = nice(spanWithBreaks / splitNumber, true);
62	    if (minInterval != null && interval < minInterval) {
63	        interval = result.interval = minInterval;
64	    }
65	    if (maxInterval != null && interval > maxInterval) {
66	        interval = result.interval = maxInterval;
67	    }
68	    // Tow more digital for tick.
69	    const precision = result.intervalPrecision = getIntervalPrecision(interval);
70	    // Niced extent inside original extent
71	    const niceTickExtent = result.niceTickExtent = [
72	        round(Math.ceil(extent[0] / interval) * interval, precision),
73	        round(Math.floor(extent[1] / interval) * interval, precision)
74	    ];
75	
76	    fixExtent(niceTickExtent, extent);
77	
78	    return result;
79	}
